// SDD kernel 利用 BCOO 行索引:
// 直接 O(1) 获取坐标，无需搜索
row = c.row_idxs[blockIdx.x];
col = c.column_idxs[blockIdx.x];

// 对比：纯 BCSR 的 SDD 需要搜索
// for row in 0..n_rows:
//     if blockIdx.x < row_offsets[row+1]: break
// 在高稀疏度（MoE 中 >90% zeros）下此搜索开销显著
```

